import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// [Start Google Fonts Loader]
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// [End Google Fonts Loader]



export type GlitchLowerThirdProps = Record<string, any>;

const GlitchLowerThird: React.FC<GlitchLowerThirdProps> = ({
  titleText = "MATTHEW YOUNG",
  subtitleText = "PHOTOGRAPHER",
  backgroundColor = "#000000",
  transparentBackground = true,
  boxColor = "#ffffff",
  textColor = "#000000",
  subtitleColor = "#ffffff",
  durationInSeconds = 5,
  animationType = "slideUp",
}) => {
  useFontLoader(["Oswald", "Roboto Condensed"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color handling
  const bgFinal = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Timing / Progress
  const exitStart = durationInSeconds * fps - 20;
  
  // Entrance Spring for Box
  const entrance = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // Entrance Spring for Text (slightly delayed)
  const textEntrance = spring({
    frame: frame - 5,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  // Exit Animation
  const exitProgress = interpolate(frame, [exitStart, exitStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  // Box Animation (Scale X)
  const boxScale = interpolate(entrance, [0, 1], [0, 1]) * (1 - exitProgress);
  
  // Text Animation (Dynamic based on type)
  const getTextTransform = () => {
    switch (animationType) {
      case "slideDown":
        return `translateY(${interpolate(textEntrance, [0, 1], [-100, 0])}%)`;
      case "slideRight": // From Left
        return `translateX(${interpolate(textEntrance, [0, 1], [-100, 0])}%)`;
      case "slideLeft": // From Right
        return `translateX(${interpolate(textEntrance, [0, 1], [100, 0])}%)`;
      case "slideUp":
      default:
        return `translateY(${interpolate(textEntrance, [0, 1], [100, 0])}%)`;
    }
  };

  const textTransform = getTextTransform();

  // Subtitle Animation
  const subtitleOpacity = interpolate(frame, [15, 30, exitStart, exitStart + 10], [0, 1, 1, 0], {
     extrapolateLeft: "clamp",
     extrapolateRight: "clamp"
  });

  // --- STYLES ---

  const containerStyle: React.CSSProperties = {
    position: "absolute",
    bottom: height * 0.15,
    left: width * 0.1,
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
    gap: "0px",
  };

  const boxStyle: React.CSSProperties = {
    backgroundColor: boxColor,
    padding: "10px 30px",
    transform: `scaleX(${boxScale})`, // Clean scale reveal
    transformOrigin: "left center",
    position: "relative",
    overflow: "hidden", // Masks the text sliding in
    boxShadow: "10px 10px 0px rgba(0,0,0,0.5)",
    border: "2px solid #000",
  };

  const textContainerStyle: React.CSSProperties = {
    overflow: "hidden", // Ensures text is masked inside the container during animation
  };

  const textStyle: React.CSSProperties = {
    fontFamily: "Oswald",
    fontSize: "80px",
    fontWeight: 700,
    color: textColor,
    textTransform: "uppercase",
    lineHeight: 1,
    position: "relative",
    zIndex: 2,
    letterSpacing: "2px",
    transform: textTransform, // Dynamic effect
    opacity: 1 - exitProgress,
  };

  const subtitleStyle: React.CSSProperties = {
    fontFamily: "Roboto Condensed",
    fontSize: "40px",
    fontWeight: 700,
    color: subtitleColor,
    textTransform: "uppercase",
    letterSpacing: "1px",
    marginTop: "10px",
    opacity: subtitleOpacity,
    transform: `translateX(${interpolate(subtitleOpacity, [0, 1], [-20, 0])}px)`,
    textShadow: "2px 2px 4px rgba(0,0,0,0.8)",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgFinal }}>
      <div style={containerStyle}>
        
        {/* Main Title Box */}
        <div style={boxStyle}>
            {/* Masked Text Container */}
            <div style={textContainerStyle}>
               <div style={textStyle}>
                  {titleText}
               </div>
            </div>
            
            {/* Clean Highlight Sheen (replaces scanlines) */}
            <div style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                background: 'linear-gradient(120deg, rgba(255,255,255,0) 40%, rgba(255,255,255,0.4) 50%, rgba(255,255,255,0) 60%)',
                transform: `translateX(${interpolate(frame, [0, 40], [-100, 200])}%)`,
                pointerEvents: 'none',
                zIndex: 10
            }} />
        </div>

        {/* Subtitle */}
        <div style={subtitleStyle}>
            {subtitleText}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default GlitchLowerThird;